//! Integer statistics.

/// Returns the arithmetic mean, rounded down, or None for empty input.
pub fn mean(values: &[u32]) -> Option<u32> {
    if values.is_empty() {
        None
    } else {
        Some(values.iter().sum::<u32>() / values.len() as u32)
    }
}

//! Duration conversion helpers.

pub fn saturating_seconds(minutes: u64) -> u64 {
    minutes.saturating_mul(60)
}

//! Page calculations.

/// Returns the number of pages needed to store items, or None for a zero page size.
pub fn pages(items: usize, page_size: usize) -> Option<usize> {
    if page_size == 0 {
        None
    } else {
        Some((items + page_size - 1) / page_size)
    }
}
